	return p != nil && p.Name != ""
}

func Less(i, j Package) bool {
	if i.Name == j.Name {
		if i.Version == j.Version {
			iLocations := i.Locations.ToSlice()
			jLocations := j.Locations.ToSlice()
			if i.Type == j.Type {
				maxLen := max(len(jLocations), len(iLocations))
				for l := range maxLen {
